select 
from lab_experiment_report r
join sys_user stu on stu.id = r.student_id
join sys_user tea on tea.id = r.teacher_id
join department d on d.id = r.department_id
left join lab l on l.id = r.lab_id
where r.deleted = 0

    and r.department_id = #{departmentId}


    and r.student_id = #{studentId}


    and r.teacher_id = #{teacherId}


    and r.status = #{status}


    and (
        r.title like concat('%', #{keyword}, '%')
        or r.experiment_name like concat('%', #{keyword}, '%')
        or r.report_no like concat('%', #{keyword}, '%')
        or stu.real_name like concat('%', #{keyword}, '%')
    )

order by r.updated_at desc, r.id desc
limit #{offset}, #{pageSize}

select count(*)
from lab_experiment_report r
join sys_user stu on stu.id = r.student_id
where r.deleted = 0

    and r.department_id = #{departmentId}


    and r.student_id = #{studentId}


    and r.teacher_id = #{teacherId}


    and r.status = #{status}


    and (
        r.title like concat('%', #{keyword}, '%')
        or r.experiment_name like concat('%', #{keyword}, '%')
        or r.report_no like concat('%', #{keyword}, '%')
        or stu.real_name like concat('%', #{keyword}, '%')
    )

select from lab_experiment_report_consumable rc join lab_experiment_report r on r.id = rc.report_id join sys_user stu on stu.id = r.student_id join sys_user tea on tea.id = r.teacher_id join lab l on l.id = rc.lab_id left join sys_user confirmer on confirmer.id = rc.confirm_user_id where r.deleted = 0 and r.status != 1
and r.department_id = #{departmentId}
and rc.status = #{status}
and rc.lab_id = #{labId}
and ( r.report_no like concat('%', #{keyword}, '%') or r.experiment_name like concat('%', #{keyword}, '%') or rc.consumable_name like concat('%', #{keyword}, '%') or stu.real_name like concat('%', #{keyword}, '%') )
order by rc.status asc, r.submitted_at desc, rc.id desc limit #{offset}, #{pageSize}

select count(*) from lab_experiment_report_consumable rc join lab_experiment_report r on r.id = rc.report_id join sys_user stu on stu.id = r.student_id where r.deleted = 0 and r.status != 1
and r.department_id = #{departmentId}
and rc.status = #{status}
and rc.lab_id = #{labId}
and ( r.report_no like concat('%', #{keyword}, '%') or r.experiment_name like concat('%', #{keyword}, '%') or rc.consumable_name like concat('%', #{keyword}, '%') or stu.real_name like concat('%', #{keyword}, '%') )

